import{_ as a,C as n,o as s,c as i,j as t,a as o,E as l,a7 as c}from"./chunks/framework.C4ZIv4ii.js";const d="/falconcms/screenshots/effects-showcase.webp",h="/falconcms/screenshots/effects-builder-border.webp",p="/falconcms/screenshots/effects-panorama.webp",g="/falconcms/screenshots/effects-product-spin.webp",u="/falconcms/screenshots/effects-product-editor.webp",D=JSON.parse('{"title":"Falcon Effects — scroll, hover, border, text and 3D effects for the Laravel page builder","description":"Falcon Effects adds scroll reveal and motion, hover packs, animated borders, particles, text effects, Lottie, a 360° panorama viewer and a 3D / 360° product view to the Falcon Builder.","frontmatter":{"title":"Falcon Effects — scroll, hover, border, text and 3D effects for the Laravel page builder","description":"Falcon Effects adds scroll reveal and motion, hover packs, animated borders, particles, text effects, Lottie, a 360° panorama viewer and a 3D / 360° product view to the Falcon Builder.","head":[["meta",{"property":"og:image","content":"https://falconcms.github.io/falconcms/screenshots/effects-showcase.webp"}]]},"headers":[],"relativePath":"builder/effects.md","filePath":"builder/effects.md","lastUpdated":1793166585000}'),f={name:"builder/effects.md"},m={id:"falcon-effects",tabindex:"-1"};function w(b,e,v,k,y,_){const r=n("Badge");return s(),i("div",null,[t("h1",m,[e[0]||(e[0]=o("Falcon Effects ",-1)),l(r,{type:"warning",text:"Pro"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#falcon-effects","aria-label":'Permalink to "Falcon Effects <Badge type="warning" text="Pro" />"'},"​",-1))]),e[3]||(e[3]=c('<p>The <strong>Falcon Effects</strong> plugin adds animations and effects to the <a href="/falconcms/builder/overview.html">Falcon Builder</a>: text that reveals itself as the page scrolls, sections that move, borders that light up, buttons and pictures that react to the mouse, particle and animated backgrounds, and a 3D view for pictures and shop products. It ships with <a href="/falconcms/guide/pro.html">FalconCMS Pro</a> and needs FalconCMS 2.8.8 or later. Activate it under <strong>Plugins</strong>.</p><p><img src="'+d+'" alt="A page built with Falcon Effects: a particle background, a typed headline and cards with a sparkling, a glare and a running-light border"></p><p>You can see every effect on this page working on the demo: <a href="https://demo.falconcms.com/effects-showcase" target="_blank" rel="noreferrer">demo.falconcms.com/effects-showcase</a>.</p><h2 id="where-the-settings-are" tabindex="-1">Where the settings are <a class="header-anchor" href="#where-the-settings-are" aria-label="Permalink to &quot;Where the settings are&quot;">​</a></h2><p>Most effects live in the <strong>Extra</strong> tab of what they change: a container, a column (nested columns too) or an element. Turn one on with its switch and its settings appear underneath. The rest are elements of their own in the <strong>Elements</strong> panel.</p><p>Every effect follows the same four rules:</p><ul><li><strong>Its script loads only where it is used.</strong> A page with no effect gets no extra script.</li><li><strong>It respects &quot;less motion&quot;.</strong> A visitor whose device asks for less motion sees the content still, with nothing hidden.</li><li><strong>It can be switched per device.</strong> Most effects can run on every device, on desktop and tablet, or on desktop only.</li><li><strong>It shows in the builder.</strong> The canvas plays the effect while you edit.</li></ul><h2 id="the-effects" tabindex="-1">The effects <a class="header-anchor" href="#the-effects" aria-label="Permalink to &quot;The effects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Effects</th></tr></thead><tbody><tr><td><strong>Scroll</strong></td><td>Scroll Reveal (color fill, fade, blur, rise, drop, grow, shrink, by letter or word), Scroll Motion (move, turn, size, opacity and blur, with ready-made parallax), Scroll Separator, Scroll Image (curtain reveals and zoom), Horizontal Scroll, Sticky Scroll Story, Stacking Cards, Scroll Color Change, Line Draw, a Counter and a Video that follow the scroll</td></tr><tr><td><strong>Mouse</strong></td><td>Mouse Tilt (with glare), Magnetic buttons, Spotlight, Image Trail, Water Ripple, Button hover packs (shine, fill, glow, ripple, confetti) and Image hover packs (zoom, grey to colour, caption, a second picture revealed)</td></tr><tr><td><strong>Borders</strong></td><td>Border Animation, twelve styles: running light, turning gradient, draws itself around, marching ants, glow pulse, neon flicker, corner brackets, two chasing lights, shifting color, sweep on hover, sparkling and glare</td></tr><tr><td><strong>Backgrounds</strong></td><td>Animated Background, Particles (constellation, snow, fireflies, dot grid and more)</td></tr><tr><td><strong>Text</strong></td><td>Typewriter, Split Text, Text Scramble, Highlight Draw (circle, underline, marker…), text styles (gradient sweep, glitch, 3D word rotate)</td></tr><tr><td><strong>Entrances</strong></td><td>Entrance Plus: flips, blur-in, wipes, a circle reveal and staggered contents</td></tr><tr><td><strong>Elements</strong></td><td>Reading Progress, Before / After, Page Effects (smooth scroll, page transitions, preloader, custom cursor), Lottie Animation, Flip Card, Text Along Path, 3D Image View</td></tr></tbody></table><h2 id="border-animation" tabindex="-1">Border Animation <a class="header-anchor" href="#border-animation" aria-label="Permalink to &quot;Border Animation&quot;">​</a></h2><p><img src="'+h+'" alt="The builder with a column&#39;s Extra tab open: Border Animation set to Sparkling, with its colours and speed, and the spark running round the column in the canvas"></p><p><strong>Extra → Border Animation</strong> animates the border of a container, a column or an element, such as a button or an image. The animation follows the box&#39;s own border and rounded corners, or draws a thin one when the box has none. Choose one of the twelve styles, when it plays (always, on hover, or from when it comes on screen), one to three colours, its width and how long one round takes.</p><ul><li><strong>Sparkling</strong> — a spark runs round the border with a short tail, throwing off sparks as it goes.</li><li><strong>Glare</strong> — a flash of light slides across the border, and faintly across the box.</li><li><strong>Hide the plain border under it</strong> leaves only the animation; <strong>Run the other way</strong> turns it round.</li></ul><h2 id="_3d-image-view" tabindex="-1">3D Image View <a class="header-anchor" href="#_3d-image-view" aria-label="Permalink to &quot;3D Image View&quot;">​</a></h2><p><img src="'+p+'" alt="The 3D Image View element showing a 360° lakeside panorama, with zoom and full-screen buttons and a &quot;Drag to look around&quot; hint"></p><p>The <strong>3D Image View</strong> element shows a picture in 3D, two ways:</p><ul><li><strong>360° panorama</strong> — a panorama photo (a phone&#39;s Panorama or Photo Sphere, or a 360 camera&#39;s picture, twice as wide as it is high) put all round the viewer. Visitors drag to look around, zoom with the buttons and open it full screen. It is drawn by a small WebGL viewer of our own: no library and no CDN.</li><li><strong>3D photo</strong> — any picture as a card with a thickness, a back and edges. Visitors drag it all the way round, or it leans towards the mouse.</li></ul><p>Either can turn by itself. It stops while someone drags it, and while it is off screen. Without WebGL, the picture is shown flat.</p><h2 id="_3d-360°-view-for-shop-products" tabindex="-1">3D / 360° view for shop products <a class="header-anchor" href="#_3d-360°-view-for-shop-products" aria-label="Permalink to &quot;3D / 360° view for shop products&quot;">​</a></h2><p><img src="'+g+'" alt="A product page with a 360° spin of a box in place of the main picture, a Pictures button, a &quot;Drag to turn it round&quot; hint and the gallery thumbnails below"></p><p>With the shop on, the product editor gets a <strong>3D / 360° View</strong> tab. The product page then shows a <strong>360°</strong> button on the main picture and a 360° tile after the gallery thumbnails. Either one puts the view in the picture&#39;s place, and any other thumbnail brings the picture back.</p><p><img src="'+u+'" alt="The product editor&#39;s 3D / 360° View tab: the kind of view, the 36 spin photos in order, and the turning speed"></p><ul><li><strong>360° spin</strong> — 8 to 72 photos taken all the way round the product, at the same distance and height and in order (24 or 36 turn smoothly). Dragging runs through them, so the product turns. <strong>Sort by file name</strong> puts them in order; <strong>Turn the other way when dragged</strong> fits photos taken the other way round.</li><li><strong>360° panorama</strong> — for a room, a car&#39;s inside or a shop: a place to look round in.</li><li><strong>3D photo</strong> — the product picture as a 3D card, turned all the way round.</li></ul><p><strong>Shown first</strong> chooses whether the page opens on the product picture or on the view.</p><h2 id="without-a-licence" tabindex="-1">Without a licence <a class="header-anchor" href="#without-a-licence" aria-label="Permalink to &quot;Without a licence&quot;">​</a></h2><p>Without a Pro licence, the settings stay in place but nothing reaches the page: the content shows as it would without the effect, and a product page shows its pictures only.</p>',26))])}const S=a(f,[["render",w]]);export{D as __pageData,S as default};
